import { registerWebComponents } from '@domg-wc/common';
import { VlLinkComponent } from '@domg-wc/components/atom';
import { VlContactCardComponent, VlInfoblockComponent, VlPropertiesComponent } from '@domg-wc/components/block';

// vl-contact-card registreert vl-infoblock, vl-properties en vl-link niet zelf. vl-properties toont elk <label> met
// de <data> die erop volgt als een paar in een lijst (<dt> en <dd>), en kloont hun inhoud naar zijn shadow DOM.
registerWebComponents([VlContactCardComponent, VlInfoblockComponent, VlPropertiesComponent, VlLinkComponent]);
